relacoes: {"destino_id": "n_e659", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_8a19", "lag_dias": 0, "origem_id": "n_08df", "tipo": "precede_FS"}
relacoes: {"destino_id": "n_a367", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_938a", "lag_dias": 0, "origem_id": "n_42be", "tipo": "precede_FS"}
relacoes: {"destino_id": "n_c820", "fonte_refs": [{"fonte_id": "f_aab5d508ec", "localizador": "L01"}], "id": "l_b6d2", "origem_id": "n_42be", "tipo": "requer"}
relacoes: {"destino_id": "n_08df", "fonte_refs": [{"fonte_id": "f_e847b102df", "localizador": "L02"}], "id": "l_d405", "lag_dias": 0, "origem_id": "n_a367", "tipo": "precede_FS"}
