      },
      {
        "fonte_id": "f_04054cfee1",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa declara orçamento de R$ 5.000,00, equivalente a 500000 centavos.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O custo de readequação não está definido; eventual cobrança por extensão depende do término efetivo."
    ],
    "motivo": "O aviso estabelece cobrança adicional de 20000 centavos, mas não determina todos os custos adicionais possíveis.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A magnitude depende do custo de readequação, não definido, e de eventual extensão do projeto."
    ],
    "motivo": "A cobrança expressa de 20000 centavos aumenta o custo; a política não prevê crédito, mas o total adicional pode ser maior.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O término condicional em D12 vale se o laudo for aceito e se mantiver o procedimento padrão. Como o aceite está pendente e a alternativa não tem duração definida, não é possível determinar o término nem o sinal da variação de dias. O custo aumenta pelo menos 20000 centavos pela cobrança explícita, mas sua magnitude total é indeterminada."
}

