      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["Duração nova de usinar corpo não fixada; pode ser qualquer inteiro não negativo."],
    "motivo": "Com a duração nova x, o término é D12 para x até 5 e D(x+7) para x maior que 5; não há valor único.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["A variação pode ser zero ou positiva; sua magnitude depende da duração nova não fixada."],
    "motivo": "O término permanece em D12 para x até 5 e atrasa para x maior que 5; portanto não se pode determinar um único sinal nem magnitude.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_b915", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "Custo de referência declarado de R$1.650,00, consistente com as obrigações base e o apoio de R$650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"}
    ],
    "lacunas": ["A duração nova e, consequentemente, eventual extensão do apoio após D12 não têm magnitude fixada."],
    "motivo": "O custo é no mínimo 167500 centavos: a base mais a cobrança direta de 2500 centavos. Se o término passar de D12, o apoio acrescenta 7500 centavos por dia excedente, sem limite informado.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {"fonte_id": "f_f2afea", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"}
    ],
    "lacunas": ["Magnitude do eventual custo adicional de apoio depende do atraso, que não está determinado."],
    "motivo": "A cobrança direta de 2500 centavos garante aumento; eventuais dias além de D12 acrescentam 7500 centavos por dia ao apoio.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A duração não fixada de usinar corpo permite término em D12 ou depois, logo a variação de prazo não tem valor nem sinal único. O custo aumenta necessariamente pela cobrança direta de 2500 centavos, mas sua magnitude pode crescer com eventual extensão do apoio."
}

